static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.storage_buffer = 1}) == VK_BUFFER_USAGE_STORAGE_BUFFER_BIT);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.index_buffer = 1}) == VK_BUFFER_USAGE_INDEX_BUFFER_BIT);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.vertex_buffer = 1}) == VK_BUFFER_USAGE_VERTEX_BUFFER_BIT);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.indirect_buffer = 1}) == VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT);
