static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.transform_feedback_buffer = 1}) == VK_BUFFER_USAGE_TRANSFORM_FEEDBACK_BUFFER_BIT_EXT);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.transform_feedback_counter_buffer = 1}) == VK_BUFFER_USAGE_TRANSFORM_FEEDBACK_COUNTER_BUFFER_BIT_EXT);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.video_decode_src = 1}) == VK_BUFFER_USAGE_VIDEO_DECODE_SRC_BIT_KHR);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.video_decode_dst = 1}) == VK_BUFFER_USAGE_VIDEO_DECODE_DST_BIT_KHR);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.video_encode_dst = 1}) == VK_BUFFER_USAGE_VIDEO_ENCODE_DST_BIT_KHR);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.video_encode_src = 1}) == VK_BUFFER_USAGE_VIDEO_ENCODE_SRC_BIT_KHR);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.shader_device_address = 1}) == VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT);
static_assert(::std::bit_cast<VkBufferUsageFlags>(buffer::usage_type{.acceleration_structure_build_input_read_only = 1}) == VK_BUFFER_USAGE_ACCELERATION_STRUCTURE_BUILD_INPUT_READ_ONLY_BIT_KHR);
